/** 月读核心 OPT.leadIn（sing-core.mjs）：第一个元音前留的秒数；块的第 0 个采样 = 第一个音的时刻 − 它。 */
export const LEAD_IN = 0.5;
/** 唱法核心 finish 的尾巴（秒）：块的声音比最后一个音长这么多。 */
export const SUNG_TAIL = 0.6;
/** 从光标放：提前这么多起放，第一个字的辅音（在元音前）不被切掉。 */
export const PRE_ROLL = 0.1;

export type Engine = "tsukuyomi" | "vowel-sampler" | "soundfont" | "unknown";
/** 一个声部上场那位的出声参数（主线程从休息室查好递进来；时间线不碰 Extras）。 */
export interface PerformerInfo {
  /** 引擎名（= 插件英文名；诊断 / 记号解读表 perform.ts 用）。 */
  engine: Engine;
  /** 这一位的哼的字（没写歌词的音唱什么；第 16 条 16-3 起只存在乐手身上、每位各自的）。 */
  hum: Hum;
  /** 上场那位的插件；null = 还没有人上场（认不出的引擎也算；ADR-0004）。出声方式 / 叠音 / 唱不唱字都问它。 */
  plugin: PerformerPlugin | null;
  /** 这位的数（每个都必填，按力度路分）；没人上场 = null。core/render.ts performerInfoOf 从拿规格的唯一的口（perfSpecOf）拿：查过的才交出来，缺了 = null、缺哪几个写在 missing 里。 */
  spec: PerfSpec | null;
  /** 这位身上缺的 / 不是数的键（门口没补上；不该有）：有 = 这个声部不出声，「不出声」清单里写清缺哪几个。 */
  missing?: string[];
  velocity: number;
  transpose: number;
  gm: { sha: string; presetIndex: number; note?: number; sfx?: SfxInfo } | null;
  chunk: SingChunkMode;
  /** 拍子轻重：这位跟多少（按乐器类别，src/score/groove.ts followOf）。 */
  follow: (s: GrooveData) => number;
  /** 跟着演奏者走的效果链（CandidateV2.chain；刀 4）。 */
  chain?: FxV2[];
  /** 着力点（v0.10.27；鼓 / 音效）：敲这个键时采样开头到「砸下去那一下」几秒——录音房提前这么多开始放，砸在写的那一拍上（反向镲 1.4 s）。
   *  有音高的乐器不给（不挪）。src/gm/percussion.ts；设计账 ai-docs/20261010-shared-staff-percussion-design.md §3。 */
  hitSec?: (key: number) => number;
  /** 这位自己的唱法参数（小月相：候选 defaults 里的旋钮，乐器页「高级」；2026-10-15）：盖在 TimelineInput.singOpt 上，一起进块的内容键。 */
  singOpt?: Record<string, unknown>;
  /** 这个声部的声音一路经过的录音房里缺的数（16-4 A2；core/render.ts mixProblemsFor 在送进来之前查的）：有 = 不出声、清单写在哪缺哪几个。 */
  mixMissing?: string[];
  /** 按块出声的（小月相）：唱法核心原始输出进轨之前乘多少（dB，乐手身上的 instrument.outputGainDb；16-4 B）。 */
  outputGainDb?: number;
  /** 按力度敲的乐器：引擎在敲的键上实际的 L（写的音高 × 力度 → dB；perform.ts VelDb，7-N）。准备声音时从库的字节算（录音房载库时），没载好 = 没有（这个声部本来就不出声）。
   *  按音量走力度的（小月相 / 元音版）不给——她们的力度就是候选身上的 dB 表（PerfSpec.dynamicsDb，16-4）。 */
  velDb?: VelDb;
}
export interface TimelineInput {
  song: Song;
  /** 放的顺序（编排；本段 = 只这一张）。 */
  order: string[];
  /** 出声的声部（静音 / 独奏已经筛过）。 */
  parts: PartDef[];
  info: (part: PartDef) => PerformerInfo;
  /** 月读核心的哼的参数（main.ts humOpt）；进内容键。 */
  singOpt: Record<string, unknown>;
}
/** 月读要唱的一块（主线程拿去让 worker 唱、按 key 喂给录音房）。 */
export interface ChunkPlan { part: string; key: string; score: LabScore; lang: SingLang; /** 给唱法核心的 opt（歌级的 + 这位自己的）；块的键里也有它。 */ opt: Record<string, unknown>; t0: number; dur: number; /** 唱的最后一个音结束的秒（不含收尾余音）。 */ end: number; /** token id → 这句里唱成第几条（按键试听「只唱这个字」用） */ entryOf: Map<number, number> }
export interface PaperSpan { paper: PaperSeg; tick0: number; t0: number; t1: number }
export interface Timeline {
  tracks: TrackSpec[];
  range: { from: number; to: number };
  /** 谱的总长（秒；不含月读的提前量 / 尾巴）。 */
  total: number;
  chunks: ChunkPlan[];
  papers: PaperSpan[];
  /** 没法出声的声部（没人上场）：不出声、报出来、人换（不自动替补）。 */
  unplayable: { part: string; why: string }[];
  /** 这个声部里 id = tokenId 的那个 token 在时间线上的秒（不是音 = 后面第一个音的时刻；不在放的范围里 = null）。 */
  secondsOfToken(partId: string, tokenId: number): number | null;
  /** 第 sec 秒落在哪张纸的第几个 tick（纸自己的 tick，反复已折回去；画播放头用）。 */
  locate(sec: number): { paperId: string; tick: number } | null;
  /** 谱位置（纸 + 纸内 tick）→ 秒：反复 / 编排里同一处放几遍 = 几个候选，取离 near 最近的；不在播放顺序里 = null。放着的时候换时间线用（播放头按谱位置留在原地）。 */
  secondsAt(paperId: string, tick: number, near: number): number | null;
}

/** 小月相唱的段和每段的语言（2026-10-13；user「打了日文之后想换成中文翻译会说不能打汉字然后报错」→「每一段里面有假名就算日文」「就是句子的单位」
 *  →「小月相不是本来就是默认模式一句一句吃的吗，用同一个深模块」）。唱（buildTimeline）、画灰（main.ts lyricMutes）都走这一个，切分只有 singChunks 一份：
 *  段 = 歌手的「分段唱」（每句 = 休止处切、每张纸、一整首）；一段的字合起来看（score/lang.ts scriptLang）：有假名 = 日（夹着的汉字照旧画灰「写成假名」）、只有汉字 = 中、只有字母 = 英；
 *  没字的段（哼）跟前一段，开头跟后面第一个有字的段；整条没字 = songLangOf（哼法定）。
 *  此前整条声部一种语言（songLangOf）：跨所有纸只要还剩一个假名就整条按日语，中文翻译打到一半每个汉字都灰、一放就「sung syllables … in the score」报错。
 *  （同日 Fable 5.1 先另写了一套切句 + 按语言再切段，跟唱的段不是同一份，Opus 5.5 收回这一个。）
 *  at = 每个 token 下标 → 它所在那段的语言（不在任何段里的 = 没有音的那几个 token，给前一段的）。 */
export interface SungPlan { ranges: [number, number][]; langs: SingLang[]; at: SingLang[] }
export function sungPlan(tokens: Token[], tempoMap: TempoMap | undefined, bounds: readonly number[], mode: SingChunkMode, hum: Hum): SungPlan {
  const ranges = singChunks(tokens, tempoMap, mode === "sheet" ? bounds : [], mode);   // 每句：只看休止，不看纸界
  const own = ranges.map(([a, b]) => { const text = tokens.slice(a, b).flatMap((t) => (t.kind === "note" && t.lyric && t.lyric !== MELISMA_MARK ? [t.lyric] : [])).join(""); return text ? scriptLang(text) : null; });
  let prev: SingLang = own.find((l) => l) ?? songLangOf(tokens, hum);
  const langs = own.map((l) => (prev = l ?? prev));
  const at: SingLang[] = new Array(tokens.length).fill(langs[0] ?? prev);
  ranges.forEach(([a, b], k) => { for (let i = a; i < tokens.length && (i < b || !ranges[k + 1]); i++) at[i] = langs[k]; });
  return { ranges, langs, at };
}
/** 一个声部每个音唱的时候按哪种语言（token id → 语言）：和唱的时候同一份 sungPlan（按编排压平 + 速度表 + 这位的分段唱）；编排没点到 / 隐藏的纸压不进来 = 那张纸自己算
 *  （没速度表，段界只差在卡着 0.25 s 的休止上）。画灰（main.ts lyricMutes）和写文件的 xml:lang（project.ts，第 16 条 16-3）都问这一处，不各算各的。 */
export function sungLangsOf(song: Song, order: readonly string[], partId: string, mode: SingChunkMode, hum: Hum): Map<number, SingLang> {
  const map = timeMapOf(song, order), flat = flattenPart(song, partId, { order }), fl = sungPlan(flat.tokens, map, flat.starts.map((s) => s.index), mode, hum).at;
  const out = new Map<number, SingLang>(flat.tokens.map((t, i) => [t.id, fl[i]!]));
  for (const paper of song.papers) {
    const toks = paper.tracks[partId]; if (!toks || !toks.some((t) => !out.has(t.id))) continue;
    const own = sungPlan(toks, undefined, [], mode, hum).at;
    toks.forEach((t, i) => { if (!out.has(t.id)) out.set(t.id, own[i]!); });
  }
  return out;
}

/** 整条声部只有一种语言时它是哪种（sungPlan 的兜底：整条没写歌词时哼什么；debug 面板的整首唱谱）：歌词里有汉字、没有假名 → 中；有字母、没假名汉字 → 英；其余按日语。 */
export function songLangOf(tokens: readonly Token[], hum: Hum): SingLang {
  const ls = tokens.flatMap((t) => (t.kind === "note" && t.lyric && t.lyric !== MELISMA_MARK ? [t.lyric] : [])).join("");
  // 英文：歌词里有拉丁字母、没有假名也没有汉字（user「好吧英文先做完」）；中英日混着的歌第一版按日 / 中唱
  if (/[A-Za-z]/.test(ls) && !/[\p{Script=Han}぀-ヿ]/u.test(ls)) return "en";
  // 整首没写歌词时，哼「啦」「呜」用中文唱（日语 ら 是轻弹舌、う 不圆唇；user「呜还是啊，拉也不行」）
  if (!ls && (hum === "la" || hum === "u")) return "zh";
  return /\p{Script=Han}/u.test(ls) && !/[぀-ヿ]/.test(ls) ? "zh" : "ja";
}

/** 滚奏一下的力度（7-N）：perform.ts rollHitVelocity 给的那个函数。 */
export type RollVel = ReturnType<typeof rollHitVelocity>;
/** 轻量版 / SoundFont 的音符表（秒）：tie 并成一个长音。marks = 修的记号怎么落到这一路上（跳音截短、呼吸处收短一口气）；不给 = 照谱满长。 */
export function lightNotes(tokens: Token[], tempoMap: TempoMap, poly = false, marks?: ReturnType<typeof lightMarks> & { /** 滚奏每秒几下（按敲的键 / 音高）；没给 = 这位不认滚奏，照一个长音放。 */ rollHz?: (midi: number) => number; }, velOf?: (index: number, art: readonly string[]) => number, rollVel?: RollVel): { midi: number; t0: number; t1: number; vel?: number; stacc?: true }[] {
  type N = { midi: number; t0: number; t1: number; vel?: number; roll?: true; stacc?: true; segs?: { index: number; t0: number; t1: number }[] };   // stacc = 写了跳音（踏板 11-3 规矩六要；拼轨之前 holdByPedals 用完就拿掉）   // segs = 滚奏音的每一段（连音线连过去的几段；7-N：每一下按落在哪一段取力度）
  const notes: N[] = [];
  let open = new Map<number, N>();   // 上一个音正在响的各音高（连音线按音高接；力度跟第一段）
  for (const { index, tok, t0, t1 } of timeline(tokens, tempoMap)) {
    if (tok.kind !== "note") continue;
    const ps = poly && tok.pitch ? allPitches(tok as NoteTok) : [effectivePitch(tokens, index)];   // 单声引擎只拿最上面那条线
    const nextOpen = new Map<number, N>();
    // 琶音（v0.9.45；v0.9.48 改：user「建议改为旋律音准时落拍、低音提前滚奏，错开间隔35ms」）：最上面的（旋律）准时落拍，下面的从低到高依次提早 arpeggioSec
    //   （最多摊到这个音一半长；连过来的那段不再错开）。歌开头那个和弦 = 低音在 0 之前滚上来（v0.16.1，user 11-07 选 A「允许在 0 之前开始滚」；原来钳在 0 = 第一个和弦合成一下，
    //   那是 v0.9.48 AI 顺手定的、不是 user 拍的）：时间线从最早的音起（同月读的辅音、鼓的着力点），第一拍照旧在 0
    const arp = poly && ps.length > 1 && marks && (tok.art ?? []).includes("arpeggio") && !tok.tie ? Math.min(marks.arpeggioSec, ((t1 - t0) * 0.5) / (ps.length - 1)) : 0;
    const rank = arp ? new Map([...ps].map((q) => midiOf(q)).sort((a, b) => a - b).map((m, k) => [m, k] as const)) : null;
    for (const p of ps) {
      const midi = midiOf(p), prev = tok.tie ? open.get(midi) : undefined;
      if (prev) { prev.t1 = prev.roll ? t1 : marks ? noteEnd(t0, t1, tok.art ?? [], marks, !!tok.slur) : t1; prev.segs?.push({ index, t0, t1 }); if ((tok.art ?? []).includes("staccato")) prev.stacc = true; else delete prev.stacc; nextOpen.set(midi, prev); continue; }   // 连过来的：跳音看最后那一段
      const roll = !!marks?.rollHz && (tok.art ?? []).includes("roll");   // 滚奏：整个音（连音线连过去的也算）敲满，见下面
      const n = { midi, t0: rank ? t0 - (ps.length - 1 - (rank.get(midi) ?? 0)) * arp : t0, t1: roll ? t1 : marks ? noteEnd(t0, t1, tok.art ?? [], marks, !!tok.slur) : t1, ...(velOf ? { vel: velOf(index, tok.art ?? []) } : {}), ...(roll ? { roll: true as const, segs: [{ index, t0, t1 }] } : {}), ...(!roll && (tok.art ?? []).includes("staccato") ? { stacc: true as const } : {}) }; notes.push(n); nextOpen.set(midi, n);
    }
    open = nextOpen;
  }
  // 滚奏（v0.16.64；user 11-07「标准滚奏记号 可以，但是要可以调整密度」）：这个音的整段切成一串等长的敲击，每秒 rollHz 下（演奏者的设置 / 乐器默认）。
  //   每一下的力度（7-N，user 11-12「这个滚奏完全没法用啊」）：按力度敲的演奏者 = rollVel 按这一下敲下去那一刻的力度水平算（渐强渐弱 / 渐到 / 音内起伏 / 强后即弱都在每一下的力度里，
  //   连音线连过去的几段各用各的；见 perform.ts rollHitVelocity）；按音量曲线走力度的 = 每一下 = 这个音的力度，渐强渐弱和音内起伏走音量曲线（gainSegments，按时间走）
  const out: { midi: number; t0: number; t1: number; vel?: number; stacc?: true }[] = [];
  for (const n of notes) {
    if (!n.roll || !marks?.rollHz) { const { segs: _s, roll: _r, ...rest } = n; out.push(rest); continue; }
    const hz = Math.max(ROLL_HZ_MIN, Math.min(ROLL_HZ_MAX, marks.rollHz(n.midi))), len = n.t1 - n.t0, k = Math.max(1, Math.round(len * hz)), d = len / k, segs = n.segs ?? [];
    const hits: { midi: number; t0: number; t1: number; vel?: number }[] = [];
    for (let i = 0; i < k; i++) {
      const t = n.t0 + i * d, seg = [...segs].reverse().find((g) => g.t0 <= t + 1e-9) ?? segs[0];
      const v = rollVel && seg ? rollVel({ index: seg.index, t, seg, first: segs[0]!.index, isFirst: i === 0, fr: len > 0 ? i / k : 0 }) : n.vel;
      hits.push({ midi: n.midi, t0: t, t1: n.t0 + (i + 1) * d, ...(v !== undefined ? { vel: v } : {}) });
    }
    // 「变化」（7-N 第三批，试验，默认没有）：左右手交替 + 小随机，种子 = 这个滚奏的音的 id（同一首歌每次一样；离线 = 实时）
    out.push(...hits);
  }
  return out.sort((a, b) => a.t0 - b.t0);   // 琶音提早的低音可能比前一个音还早一点：按起点排（稳定排序：没琶音的歌顺序原样）
}

export const HUM_KANA: Record<Hum, string> = { la: "ら", n: "ん", u: "う", o: "お", a: "あ" };

export function buildTimeline(inp: TimelineInput): Timeline {
  const { song, order } = inp;
  const map = timeMapOf(song, order), gmap = grooveMapOf(song, order);   // 时间表 = 速度 + 摇摆（v0.9.36：三种演奏者同一个扭曲）
  const flats = new Map<string, { tokens: Token[]; starts: { index: number; paper: PaperSeg }[] }>();
  const flat = (partId: string) => { let f = flats.get(partId); if (!f) { f = flattenPart(song, partId, { order }); flats.set(partId, f); } return f; };
  const tracks: TrackSpec[] = [], chunks: ChunkPlan[] = [], unplayable: { part: string; why: string }[] = [];
  let total = 0, from = 0, to = 0;
  for (const part of inp.parts) {
    const { tokens, starts } = flat(part.id), bounds = starts.map((s) => s.index), tl = timeline(tokens, map);
    if (tl.length) total = Math.max(total, tl[tl.length - 1].t1);
    const info = inp.info(part);
    if (!info.plugin) { unplayable.push({ part: part.id, why: _t("还没有人上场") }); continue; }
    if (info.missing?.length) { unplayable.push({ part: part.id, why: _t("这位乐手身上缺这几个数，没有出声：{keys}", { keys: info.missing.join("、") }) }); continue; }   // 先于下一行：缺数的规格不交出来（spec = null），原因照实说缺哪几个
    if (!info.spec) { unplayable.push({ part: part.id, why: _t("还没有人上场") }); continue; }
    if (info.mixMissing?.length) { unplayable.push({ part: part.id, why: _t("混音台上缺这几个数，没有出声：{keys}", { keys: info.mixMissing.join("；") }) }); continue; }
    const groove = grooveWeights(tokens, bounds, gmap, info.follow);
    const sp = info.spec, byVel = sp.path === "velocity";   // 按力度敲（乐器）/ 按音量曲线（小月相 / 元音版）= 插件报的路，规格跟着它分（16-4 A）
    // L（dB ↔ 力度只经过它，7-N）：按力度敲的 = 引擎在敲的键上实际的（准备声音时从库算；没载好 = 没有，这个声部本来就不出声，不换算）
    const curve: VelDb = byVel ? info.velDb ?? NO_CURVE : NO_CURVE;   // 按力度敲的 = 引擎在敲的键上实际的 L；按音量走的不用（她们的力度就是 dB 表，16-4）
    const rolls = info.plugin.honors.includes("roll");
    const gain: GainSeg[] | null = gainSegments(tokens, map, sp, bounds, groove, curve, rolls);
    if (info.plugin.sound === "chunks") {   // 慢引擎：按句出块（谁唱由 worker 按插件定；现在只有小月相）
      const plan = sungPlan(tokens, map, bounds, info.chunk, info.hum);   // 段 + 每段的语言（画灰也走它）
      const noteAt = (a: number) => tl.find((x) => x.index >= a && x.tok.kind === "note")?.t0 ?? 0;
      const clips: TrackSpec & { kind: "clips" } = { id: part.id, kind: "clips", clips: [], gain, ...(info.chain?.length ? { chain: info.chain } : {}) };
      for (const [k, [a, b]] of plan.ranges.entries()) {
        const lang = plan.langs[k], te = new Map<number, number>(), score = toLabScore(tokens, info.hum, lang, map, sp.sing, [a, b], te);
        if (!score.SCORE.length) continue;
        const entryOf = new Map<number, number>(); for (const [i, e] of te) entryOf.set(tokens[i].id, e);
        const first = noteAt(a), last = tl.filter((x) => x.index >= a && x.index < b && x.tok.kind === "note").reduce((m, x) => Math.max(m, x.t1), first);
        const opt = { ...inp.singOpt, ...(info.singOpt ?? {}) };   // 歌级的哼的参数 + 这位自己的旋钮（候选里按值存的）
        const key = JSON.stringify(["tsukuyomi-chunk", score, opt]), t0 = first - LEAD_IN, dur = last - first + LEAD_IN + SUNG_TAIL;
        clips.clips.push({ key, t0, dur, gain: 10 ** (info.outputGainDb! / 20), end: last });   // 块乘多少 = 这位乐手身上写的（16-4 B；缺了 = 送进来之前就报了缺数、到不了这里）
        chunks.push({ part: part.id, key, score, lang, opt, t0, dur, end: last, entryOf });
        from = Math.min(from, t0); to = Math.max(to, t0 + dur);
      }
      tracks.push(clips);
      continue;
    }
    const vels = sp.path === "velocity" ? noteVelocities(tokens, map, sp, info.velocity, bounds, groove) : null;   // 按音量曲线的：每个音一样的力度（力度记号在曲线上）
    // 滚奏的密度（v0.16.64）：这位身上写的那个数（16-4 F 起只写数：新上场 / 门口按是不是鼓从模板抄）。这位不认滚奏（honors 里没有）= 照一个长音放
    const rollHz = info.plugin.honors.includes("roll") ? () => sp.rollHz : undefined;
    const rollVel0 = rollHz && sp.path === "velocity" ? rollHitVelocity(tokens, map, sp, info.velocity, bounds, groove, curve) : undefined;   // 滚奏的每一下按当时的力度水平（7-N；按音量曲线的照旧）
    // 踏板（11-1 延音、11-2 持音 / 弱音；score/pedal.ts）：这位认哪几种 = 插件报的 pedals；不认 = 照写的（记号画灰、明说）
    const pk = info.plugin.pedals ?? [];
    // 弱音（规矩五）：踩着期间起的音力度加这位身上的 softVel——按这个音写的起点算（琶音提早的下面几个音也算在这个和弦里），滚奏按每一下自己那一刻
    const soft = pk.includes("soft") && sp.path === "velocity" ? softAt(pedalSpans(tokens, map, bounds, "soft")) : null, softVel = sp.path === "velocity" ? sp.softVel : 0;
    const t0Of = soft ? new Map(tl.map((x) => [x.index, x.t0])) : null;
    const velOf = (i: number) => { const v = vels?.get(i) ?? info.velocity; return soft && soft(t0Of!.get(i) ?? 0) ? softened(v, softVel) : v; };
    const rollVel: RollVel | undefined = rollVel0 && soft ? (h) => { const v = rollVel0(h); return soft(h.t) ? softened(v, softVel) : v; } : rollVel0;
    const notes0 = lightNotes(tokens, map, info.plugin.poly, { ...lightMarks(sp), ...(rollHz ? { rollHz } : {}) }, velOf, rollVel);
    // 键按多久 = 谱上的延音 / 持音踏板 → 照写的时值
    //   延音那一种每一段开头的状态 = 这位身上写的「没写踏板记号时留不留」（踏板 11-3，规矩一；按力度敲的才有这个键，出声的代码不带默认）
    const sus = pk.includes("sustain") ? pedalSpans(tokens, map, bounds, "sustain", sp.path === "velocity" && sp.pedal === "down") : [], sost = pk.includes("sostenuto") ? pedalSpans(tokens, map, bounds, "sostenuto") : [];
    const notes = holdByPedals(notes0, sus, sost).map(({ stacc: _s, ...n }) => n);   // stacc 只给规矩六用，不进轨
    // 快引擎：音符表 → 这位的轨，怎么拼归插件（元音版 / SoundFont 的键 / 着力点都在它自己那里；ADR-0004）
    const built = info.plugin.track?.({ id: part.id, notes, gain, ...(info.chain?.length ? { chain: info.chain } : {}), hum: info.hum, info });
    if (!built) { unplayable.push({ part: part.id, why: _t("「{label}」不会按音符表出声", { label: info.plugin.label }) }); continue; }
    if ("unplayable" in built) { unplayable.push({ part: part.id, why: built.unplayable }); continue; }
    if (built.from !== undefined) from = Math.min(from, built.from);   // 着力点提前了的音：比第一个音还早 = 时间线从那儿起（同月读的辅音提前）
    tracks.push(built.track);
  }
  to = Math.max(to, total);
  // 纸的秒区间（所有声部压平后的纸序列一样：缺这个声部的纸补了休止）
  const ref = inp.parts[0] ?? song.parts[0];
  const papers: PaperSpan[] = [];
  if (ref) {
    const { tokens, starts } = flat(ref.id), tl = timeline(tokens, map);
    const secAt = (index: number) => tl.find((x) => x.index >= index)?.t0 ?? (tl.length ? tl[tl.length - 1].t1 : 0);
    const tickAt = (index: number) => tl.find((x) => x.index >= index)?.start ?? (tl.length ? tl[tl.length - 1].start + tl[tl.length - 1].tok.dur : 0);
    starts.forEach((s, k) => { const nextIndex = starts[k + 1]?.index ?? tokens.length; papers.push({ paper: s.paper, tick0: tickAt(s.index), t0: secAt(s.index), t1: secAt(nextIndex) }); });
    if (papers.length && tl.length) papers[papers.length - 1].t1 = tl[tl.length - 1].t1;
  }
  const secondsOfToken = (partId: string, tokenId: number): number | null => {
    const f = flats.get(partId) ?? flat(partId), tl = timeline(f.tokens, map);
    const i = f.tokens.findIndex((t) => t.id === tokenId); if (i < 0) return null;
    return tl.find((x) => x.index >= i)?.t0 ?? (tl.length ? tl[tl.length - 1].t1 : null);
  };
  /** 这张纸的反复结构——按原件算（starts 里的 paper 是展开后的那份：反复小节线已经被展开吃掉，拿它算永远是 null；2026-10-10 修，之前第二遍 locate 回的 tick 超出纸长）。 */
  const segsOf = (paperId: string) => { const pp = song.papers.find((x) => x.id === paperId), owner = pp ? tempoOwner(song, pp) : null; return pp && owner ? playSegments(pp.tracks[owner], paperTicks(pp)) : null; };
  const locate = (sec: number): { paperId: string; tick: number } | null => {
    if (!ref) return null;
    const { tokens } = flat(ref.id), tl = timeline(tokens, map);
    const e = tl.find((x) => sec >= x.t0 && sec < x.t1) ?? (sec >= 0 && tl.length && sec < tl[tl.length - 1].t1 + 1e-9 ? tl[tl.length - 1] : null);
    if (!e) return null;
    const tick = e.start + ((sec - e.t0) / Math.max(1e-9, e.t1 - e.t0)) * e.tok.dur;
    let span = papers[0]; for (const p of papers) if (p.tick0 <= tick + 1e-9) span = p;
    if (!span) return null;
    let inPaper = tick - span.tick0;
    // 谱内反复展开过：展开后的 tick → 纸自己的 tick（src/score/repeats.ts）
    const segs = segsOf(span.paper.id);
    if (segs) { let cum = 0; for (const s of segs) { const len = s.t1 - s.t0; if (inPaper < cum + len) { inPaper = s.t0 + (inPaper - cum); break; } cum += len; } }
    return { paperId: span.paper.id, tick: Math.max(0, Math.floor(inPaper)) };
  };
  const secondsAt = (paperId: string, tick: number, near: number): number | null => {
    if (!ref) return null;
    const { tokens } = flat(ref.id), tl = timeline(tokens, map);
    let best: number | null = null;
    for (const span of papers) {
      if (span.paper.id !== paperId) continue;
      const segs = segsOf(span.paper.id);
      const cands: number[] = [];   // 纸自己的 tick → 展开后的 tick（反复 = 几个）
      if (segs) { let cum = 0; for (const sg of segs) { if (tick >= sg.t0 && tick < sg.t1) cands.push(span.tick0 + cum + (tick - sg.t0)); cum += sg.t1 - sg.t0; } }
      else cands.push(span.tick0 + tick);
      for (const T of cands) {
        const e = tl.find((x) => T >= x.start && T < x.start + x.tok.dur); if (!e) continue;
        const sec = e.t0 + ((T - e.start) / Math.max(1e-9, e.tok.dur)) * (e.t1 - e.t0);
        if (best === null || Math.abs(sec - near) < Math.abs(best - near)) best = sec;
      }
    }
    return best;
  };
  return { tracks, range: { from, to }, total, chunks, papers, unplayable, secondsOfToken, locate, secondsAt };
}
